117	export function buildAuthorizeUrl(params: {
118	  clientId: string;
119	  redirectUri: string;
120	  state: string;
121	  challenge: string;
122	}): string {
123	  const url = new URL(AUTHORIZATION_ENDPOINT);
124	  url.searchParams.set("response_type", "code");
125	  url.searchParams.set("client_id", params.clientId);
126	  url.searchParams.set("redirect_uri", params.redirectUri);
127	  url.searchParams.set("scope", SCOPE);
128	  url.searchParams.set("state", params.state);
129	  url.searchParams.set("code_challenge", params.challenge);
130	  url.searchParams.set("code_challenge_method", "S256");
131	  // RFC 8707: bind the token to the MCP endpoint specifically.
132	  url.searchParams.set("resource", FIRECRAWL_MCP_URL);
133	  return url.toString();
134	}
