1	// Firecrawl MCP OAuth client — server-side only (imported by API routes).
2	//
3	// Implements the app side of Firecrawl's keyless MCP endpoint
4	// (https://mcp.firecrawl.dev/v2/mcp): OAuth 2.0 Authorization Code + PKCE
5	// (S256) with RFC 7591 Dynamic Client Registration and RFC 8707 resource
6	// indicators, per docs.firecrawl.dev/developer-guides/mcp-setup-guides/oauth.
7	//
8	// Why this lives on our server: the OpenAI Realtime API is the MCP *client*
9	// that executes tool calls — it only needs a bearer token in the session's
10	// tool config. This module owns obtaining and refreshing that token. The
11	// browser only ever sees the short-lived scoped access token, never a raw
12	// `fc-` API key — which is the point of the OAuth path.
13	//
14	// The registered client id and tokens persist in `.firecrawl/oauth.json`
15	// (gitignored). Access tokens expire after ~1h; refresh tokens rotate on
16	// every use, so the store is rewritten on each refresh. Dev only — no
17	// production yet, same as the rest of the secrets story.
18	
19	import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
20	import { createHash, randomBytes } from "node:crypto";
21	import { dirname, join } from "node:path";
22	
23	const AUTHORIZATION_ENDPOINT = "https://www.firecrawl.dev/api/oauth/authorize";
24	const TOKEN_ENDPOINT = "https://www.firecrawl.dev/api/oauth/token";
25	const REGISTRATION_ENDPOINT = "https://www.firecrawl.dev/api/oauth/register";
26	const SCOPE = "firecrawl:global";
27	
28	/** Keyless MCP endpoint — both the RFC 8707 resource and the Realtime tool's server_url. */
29	export const FIRECRAWL_MCP_URL = "https://mcp.firecrawl.dev/v2/mcp";
30	
31	const STORE_PATH = join(process.cwd(), ".firecrawl", "oauth.json");
32	/** Refresh this many ms before the recorded expiry to absorb clock skew. */
33	const EXPIRY_SLACK_MS = 60_000;
34	
35	interface StoredClient {
36	  client_id: string;
37	  redirect_uri: string;
38	}
39	
40	interface StoredTokens {
41	  access_token: string;
42	  refresh_token?: string;
43	  /** Absolute epoch ms when access_token expires. */
44	  expires_at: number;
45	}
46	
47	interface OauthStore {
48	  client?: StoredClient;
49	  tokens?: StoredTokens;
50	}
51	
52	function loadStore(): OauthStore {
53	  try {
54	    return JSON.parse(readFileSync(STORE_PATH, "utf8")) as OauthStore;
55	  } catch {
56	    return {};
57	  }
58	}
59	
60	function saveStore(store: OauthStore): void {
61	  mkdirSync(dirname(STORE_PATH), { recursive: true });
62	  writeFileSync(STORE_PATH, JSON.stringify(store, null, 2) + "\n", { mode: 0o600 });
63	}
64	
65	function base64url(buf: Buffer): string {
66	  return buf.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
67	}
68	
69	export interface Pkce {
70	  verifier: string;
71	  challenge: string;
72	}
73	
74	/** RFC 7636 PKCE pair; Firecrawl supports S256 only. */
75	export function createPkce(): Pkce {
76	  const verifier = base64url(randomBytes(32));
77	  const challenge = base64url(createHash("sha256").update(verifier).digest());
78	  return { verifier, challenge };
79	}
80	
81	export function createState(): string {
82	  return base64url(randomBytes(16));
83	}
84	
85	/**
86	 * Dynamic Client Registration (RFC 7591). Firecrawl issues public clients
87	 * (`token_endpoint_auth_method: "none"`), so there is no secret to keep.
88	 * The client_id is cached in the store and reused while the redirect_uri
89	 * (derived from the dev server origin) stays the same.
90	 */
91	export async function ensureClient(redirectUri: string): Promise<string> {
92	  const store = loadStore();
93	  if (store.client && store.client.redirect_uri === redirectUri) {
94	    return store.client.client_id;
95	  }
96	  const res = await fetch(REGISTRATION_ENDPOINT, {
97	    method: "POST",
98	    headers: { "Content-Type": "application/json" },
99	    body: JSON.stringify({
100	      client_name: "Tsubaki realtime voice console (dev)",
101	      redirect_uris: [redirectUri],
102	      grant_types: ["authorization_code", "refresh_token"],
103	      response_types: ["code"],
104	      token_endpoint_auth_method: "none",
105	      scope: SCOPE,
106	    }),
107	  });
108	  if (!res.ok) {
109	    throw new Error(`Firecrawl client registration failed (${res.status})`);
110	  }
111	  const data = (await res.json()) as { client_id?: string };
112	  if (!data.client_id) throw new Error("Firecrawl registration returned no client_id");
113	  saveStore({ ...store, client: { client_id: data.client_id, redirect_uri: redirectUri } });
114	  return data.client_id;
115	}
