117	export function buildAuthorizeUrl(params: {
118	  clientId: string;
119	  redirectUri: string;
120	  state: string;
121	  challenge: string;
122	}): string {
123	  const url = new URL(AUTHORIZATION_ENDPOINT);
124	  url.searchParams.set("response_type", "code");
125	  url.searchParams.set("client_id", params.clientId);
126	  url.searchParams.set("redirect_uri", params.redirectUri);
127	  url.searchParams.set("scope", SCOPE);
128	  url.searchParams.set("state", params.state);
129	  url.searchParams.set("code_challenge", params.challenge);
130	  url.searchParams.set("code_challenge_method", "S256");
131	  // RFC 8707: bind the token to the MCP endpoint specifically.
132	  url.searchParams.set("resource", FIRECRAWL_MCP_URL);
133	  return url.toString();
134	}
135	
136	interface TokenResponse {
137	  access_token?: string;
138	  refresh_token?: string;
139	  expires_in?: number;
140	}
141	
142	async function requestTokens(body: URLSearchParams): Promise<StoredTokens> {
143	  const res = await fetch(TOKEN_ENDPOINT, {
144	    method: "POST",
145	    headers: { "Content-Type": "application/x-www-form-urlencoded" },
146	    body,
147	  });
148	  if (!res.ok) {
149	    throw new Error(`Firecrawl token request failed (${res.status})`);
150	  }
151	  const data = (await res.json()) as TokenResponse;
152	  if (!data.access_token) throw new Error("Firecrawl token response had no access_token");
153	  return {
154	    access_token: data.access_token,
155	    refresh_token: data.refresh_token,
