160	/** Authorization-code exchange; persists the resulting tokens. */
161	export async function exchangeCode(params: {
162	  code: string;
163	  verifier: string;
164	  redirectUri: string;
165	  clientId: string;
166	}): Promise<void> {
167	  const tokens = await requestTokens(
168	    new URLSearchParams({
169	      grant_type: "authorization_code",
170	      code: params.code,
171	      redirect_uri: params.redirectUri,
172	      client_id: params.clientId,
173	      code_verifier: params.verifier,
174	      resource: FIRECRAWL_MCP_URL,
175	    }),
176	  );
177	  saveStore({ ...loadStore(), tokens });
178	}
179	
