182	 * rotated refresh token) when the stored one is expired or about to expire.
183	 * Returns null when the user hasn't completed the OAuth flow yet.
184	 */
185	export async function getValidAccessToken(): Promise<string | null> {
186	  const store = loadStore();
187	  const tokens = store.tokens;
188	  if (!tokens) return null;
189	  if (tokens.expires_at - EXPIRY_SLACK_MS > Date.now()) return tokens.access_token;
190	  if (!tokens.refresh_token || !store.client) return null;
191	  try {
192	    const next = await requestTokens(
193	      new URLSearchParams({
194	        grant_type: "refresh_token",
195	        refresh_token: tokens.refresh_token,
196	        client_id: store.client.client_id,
197	        resource: FIRECRAWL_MCP_URL,
198	      }),
199	    );
200	    // Rotating refresh tokens: keep the old one only if none was returned.
201	    saveStore({
202	      ...store,
203	      tokens: { ...next, refresh_token: next.refresh_token ?? tokens.refresh_token },
204	    });
205	    return next.access_token;
206	  } catch {
207	    return null;
208	  }
209	}

